ZIP_SHA='3bff38d65384f3508a4fc3826c7f9d05f99b89d1d1d6433314999d8dbc8a146d'
BASE=Path(__file__).resolve().parent/'LDL_25_Expanded_Run'
def sha(raw):return hashlib.sha256(raw).hexdigest()
def fetch(url,expected):
 last=None
 urls=[url,url.replace('https://raw.githubusercontent.com/','https://github.com/').replace('/datasets/','/datasets/')]
 # GitHub alternate raw route retains the same repository and pinned revision.
 parts=url.removeprefix('https://raw.githubusercontent.com/').split('/')
 urls=[url,'https://github.com/'+ '/'.join(parts[:2])+'/raw/'+ '/'.join(parts[2:])]
 for attempt in range(4):
  for address in urls:
   try:
    print('DOWNLOAD',address,flush=True)
    with urllib.request.urlopen(address,timeout=180) as response:raw=response.read()
    if sha(raw)==expected:return raw
    # Vendored snapshots normalize CRLF to LF and may add one final newline.
    normalized=raw.replace(b'\r\n',b'\n')
    for value in [normalized,raw+b'\n',normalized+b'\n',normalized.rstrip(b'\n')+b'\n']:
     if sha(value)==expected:return value
    raise ValueError('Upstream file hash mismatch')
   except Exception as e:last=e;print('Retry:',str(e),flush=True)
  time.sleep(2)
 raise RuntimeError(f'Cannot retrieve verified file: {url}: {last}')
def main():
 if sys.version_info[:2]!=(3,12):raise RuntimeError('Use 64-bit Python 3.12')
 raw=base64.b85decode(PAYLOAD);assert sha(raw)==ZIP_SHA
 with zipfile.ZipFile(io.BytesIO(raw)) as z:
  for name in z.namelist():assert not Path(name).is_absolute() and '..' not in Path(name).parts
  # Never overwrite a different installed implementation during a resumed run.
  for name in z.namelist():
   p=BASE/name;content=z.read(name)
   if p.exists():assert p.read_bytes()==content,('Existing file differs',str(p))
   else:p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(content)
 print('Installed experiment code and frozen inputs:',BASE,flush=True)
 if '--extract-only' in sys.argv:return
